insert into benefit_rules (id, card_id, valid_from, status, rule) values ('wr_park', 'woori_rentalfree', null, 'approved', '{"confidence":0.8,"supported":false,"id":"wr_park","cardId":"woori_rentalfree","name":"놀이공원 자유이용권 본인 50% 현장할인","kind":"discount","rate":0.5,"target":{"merchants":["에버랜드","롯데월드","서울랜드","이월드","경주월드","통도환타지아"]},"limitsByTier":[{"tier":{"min":300000,"max":700000},"monthlyCount":1,"yearlyCount":10},{"tier":{"min":700000,"max":1000000},"monthlyCount":1,"yearlyCount":10},{"tier":{"min":1000000,"max":null},"monthlyCount":1,"yearlyCount":10}],"unsupportedReason":"놀이공원 현장할인 — 결제액이 이미 할인된 금액이라 청구 기준 계산 불가 · 놀이공원 업종도 없음","rawText":"전국 놀이공원 자유이용권 본인 50% 할인(현장할인). 에버랜드, 롯데월드, 서울랜드, 이월드(대구), 경주월드, 통도환타지아. 통합 월 1회, 연 10회 한도. 전월실적 30만원 이상 시 제공"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
insert into card_products (id, issuer, name, type, color, grade, annual_fee, tiers, spend_excludes, variants, perks, source_url, checked_at, review_status) values ('lotte_cuckoo', '롯데카드', '쿠쿠 롯데카드', 'credit', '#C8102E', 'C', 20000, '[{"min":0,"max":400000},{"min":400000,"max":800000},{"min":800000,"max":1600000},{"min":1600000,"max":null}]'::jsonb, array['tax','school','gas','electric','utility','apt_fee','gift_card','taxi','transit']::text[], null, '[{"id":"lc_k_install","kind":"installment","name":"쿠쿠 장기할부 월 캐시백","detail":"쿠쿠에서 40만원 이상 24·36개월 장기할부(연 7.0%) 시 다음 달부터 36개월차까지 매월 26일 8천~2만4천원 캐시백. 렌탈료 할인과 중복 안 됨","rawText":"쿠쿠 롯데카드로 쿠쿠에서 40만원 이상 장기 할부 이용시 혜택. 지난달 이용실적 40만원 이상 8,000원 / 80만원 이상 12,000원 / 160만원 이상 24,000원, 이번 달 26일 캐시백 지급(월1회). 장기 할부 이용월 기준 다음 달부터 36개월차까지 혜택이 제공됩니다. 렌탈료 결제일 할인과 장기 할부 캐시백은 중복 제공 되지 않습니다."}]'::jsonb, 'https://www.lottecard.co.kr/app/LPCDADB_V100.lc?vtCdKndC=P15895-A15895', '2026-10-11', 'approved') on conflict (id) do update set issuer=excluded.issuer, name=excluded.name, type=excluded.type, color=excluded.color, grade=excluded.grade, annual_fee=excluded.annual_fee, tiers=excluded.tiers, spend_excludes=excluded.spend_excludes, variants=excluded.variants, perks=excluded.perks, source_url=excluded.source_url, checked_at=excluded.checked_at, review_status=excluded.review_status;
insert into benefit_rules (id, card_id, valid_from, status, rule) values ('lc_rental', 'lotte_cuckoo', null, 'approved', '{"confidence":0.9,"supported":true,"kind":"discount","rate":1,"id":"lc_rental","cardId":"lotte_cuckoo","name":"쿠쿠 렌탈료 결제일 할인","target":{"autoPayOnly":true,"merchants":["쿠쿠"]},"limitsByTier":[{"tier":{"min":400000,"max":800000},"monthlyCap":8000},{"tier":{"min":800000,"max":1600000},"monthlyCap":12000},{"tier":{"min":1600000,"max":null},"monthlyCap":24000}],"rawText":"쿠쿠 렌탈료 결제 시 결제일 할인. 자동납부 필수, 월 횟수 제한 없음. 지난달 카드 이용 실적 40만원 이상 8,000원 / 80만원 이상 12,000원 / 160만원 이상 24,000원. 지난달 이용금액이 40만원 미만인 경우는 결제일 할인이 되지 않습니다. 렌탈료 자동 납부 승인 건이 여러 건인 경우 월 할인 한도 내에서 할인 됩니다. 렌탈료가 렌탈료 할인 한도보다 적을 경우 렌탈료 만큼만 할인됩니다."}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
