insert into benefit_rules (id, card_id, valid_from, status, rule) values ('ic_rental', 'ibk_coway', null, 'approved', '{"confidence":0.9,"supported":true,"kind":"discount","rate":1,"id":"ic_rental","cardId":"ibk_coway","name":"코웨이·웅진 렌탈료 자동이체 청구할인","target":{"autoPayOnly":true,"merchants":["코웨이","웅진"]},"limitsByTier":[{"tier":{"min":300000,"max":700000},"monthlyCap":13000},{"tier":{"min":700000,"max":1200000},"monthlyCap":17000},{"tier":{"min":1200000,"max":null},"monthlyCap":23000}],"rawText":"코웨이 렌탈료 자동이체 결제시 최대 23,000원 청구할인. 웅진 렌탈료 자동이체 결제 시 청구할인. 전월이용실적 30만원 이상 13,000원 / 70만원 이상 17,000원 / 120만원 이상 23,000원 (통합할인한도). 렌탈료 자동이체 필수. 자동이체 건이 여러 건인 경우에도 합산하여 할인한도 내에서 할인 적용. 렌탈료가 렌탈료 할인금액보다 적을 경우 렌탈료 납부금액 내에서 할인 적용"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
