insert into benefit_rules (id, card_id, valid_from, status, rule) values ('nr_rental', 'nh_rental_coway', null, 'approved', '{"confidence":0.9,"supported":true,"kind":"discount","rate":1,"id":"nr_rental","cardId":"nh_rental_coway","name":"코웨이 렌탈료 청구할인","target":{"autoPayOnly":true,"merchants":["코웨이"]},"limitsByTier":[{"tier":{"min":300000,"max":1000000},"monthlyCap":10000},{"tier":{"min":1000000,"max":2000000},"monthlyCap":15000},{"tier":{"min":2000000,"max":null},"monthlyCap":30000}],"rawText":"매월 코웨이 렌탈료 1~3만원 청구할인. 전월실적 30만원이상 1만원 / 100만원이상 1만5천원 / 200만원이상 3만원. 전월실적 산정 시 코웨이 렌탈 이용액은 제외됩니다. 렌탈료 승인금액이 할인받을 금액보다 적을 경우 승인금액만큼 할인 적용됩니다. 렌탈료 1만원 2건 인 경우 : 각 1만원, 5천원 (총 1만5천원) 할인. 코웨이 렌탈료 할인 서비스는 해당카드로 렌탈료 자동이체 신청 시 적용됩니다."}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
insert into benefit_rules (id, card_id, valid_from, status, rule) values ('nr_park', 'nh_rental_coway', null, 'approved', '{"confidence":0.8,"supported":false,"id":"nr_park","cardId":"nh_rental_coway","name":"놀이공원 본인 30~50% 현장할인","kind":"discount","rate":0.5,"target":{"merchants":["에버랜드","롯데월드","서울랜드","이월드","경주월드","통도환타지아","광주패밀리랜드","한국민속촌"]},"limitsByTier":[{"tier":{"min":300000,"max":1000000},"monthlyCount":1,"yearlyCount":6},{"tier":{"min":1000000,"max":2000000},"monthlyCount":1,"yearlyCount":6},{"tier":{"min":2000000,"max":null},"monthlyCount":1,"yearlyCount":6}],"unsupportedReason":"놀이공원 현장할인 — 결제액이 이미 할인된 금액이라 청구 기준 계산 불가 · 놀이공원 업종도 없음","rawText":"전국 주요 놀이공원 할인 (통합 월1회, 연6회). 에버랜드, 롯데월드, 서울랜드, 통도환타지아, 어뮤즈먼트(경주월드), 이월드(대구), 광주패밀리랜드, 한국민속촌(용인): 본인 자유이용권 50% 현장할인. 캐리비안베이, 캘리포니아비치(경주월드): 본인 입장료 30% 현장할인. 아쿠아환타지아(통도): 본인 및 동반1인 입장료 30% 현장할인. 전주시 동물원: 본인 무료 입장(청구할인). 전월실적 30만원 이상 시 제공"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
insert into card_products (id, issuer, name, type, color, grade, annual_fee, tiers, spend_excludes, variants, perks, source_url, checked_at, review_status) values ('kb_narasarang', 'KB국민카드', '나라사랑카드(체크)', 'check', '#55603A', 'D', 0, '[{"min":0,"max":100000},{"min":100000,"max":200000},{"min":200000,"max":300000},{"min":300000,"max":500000},{"min":500000,"max":1000000},{"min":1000000,"max":null}]'::jsonb, array['transit','overseas']::text[], null, '[{"id":"kbn_k_pop","kind":"status","name":"GS리테일 POP 서비스","detail":"GS25·GS더프레시 행사상품 할인·1+1·GS ALL POINT 추가 적립. 실적 무관, GS25 해군마트 제외","rawText":"GS리테일 팝서비스: GS25, GS더프레시에서 행사 상품 구매 시 할인, 1+1, GS ALL POINT 추가 적립 등 365일 다양한 서비스. 전월 이용실적과 무관하게 서비스 혜택 제공. GS25 해군마트는 팝서비스 제공 제외"},{"id":"kbn_k_ins","kind":"etc","name":"상해보험 무료 가입","detail":"KB손해보험 단체보험. 군부대 내외 사고 최대 5천만원, 부대 밖 대중교통상해 최대 1억원 (현역 복무 중)","rawText":"KB손해보험 단체보험 무료 가입. 군부대 내외 화재, 폭발, 붕괴사고 최대 5천만원 보장. 군부대 외 일반사고 최대 5천만원 보장. 군부대 외 대중교통상해 최대 1억원 보장. 상기 서비스는 현역 복무 중인 경우에만 제공"},{"id":"kbn_k_event","kind":"etc","name":"경조사 서비스","detail":"본인 부모 조사 시 꽃바구니 2개, 본인 결혼 시 화환 2개 (현역 복무 중)","rawText":"본인 부모조사(弔死) 발생 시 제단 꽃바구니 2개 증정. 본인 결혼 시 축하 화환 2개 증정"},{"id":"kbn_k_fee","kind":"fee_waiver","name":"금융수수료 면제","detail":"국군재정관리단 급여이체 시 KB·타행 ATM 인출, 인터넷·모바일 타행이체 수수료 면제","rawText":"국군재정관리단을 통한 급여이체 시 서비스 제공. KB국민은행 자동화기기 인출 및 이체 수수료 면제. KB국민은행 외(타행) 자동화기기 인출 수수료 면제. 인터넷, 모바일, 폰뱅킹 타행이체 수수료 면제"},{"id":"kbn_k_first","kind":"etc","name":"발급 초기 실적 면제","detail":"첫 사용 등록일부터 다음 달 말일까지 실적 없이 월 1만원 한도로 할인 (대중교통·통신 자동이체 제외)","rawText":"최초 카드 사용등록일로부터 다음달 말일까지 이용실적이 없어도 월간 할인한도 1만원 이내에서 할인. 단, 대중교통 요금할인, 통신요금 자동이체 할인 서비스는 제외"}]'::jsonb, 'https://m.kbcard.com/c/04120', '2026-10-11', 'approved') on conflict (id) do update set issuer=excluded.issuer, name=excluded.name, type=excluded.type, color=excluded.color, grade=excluded.grade, annual_fee=excluded.annual_fee, tiers=excluded.tiers, spend_excludes=excluded.spend_excludes, variants=excluded.variants, perks=excluded.perks, source_url=excluded.source