insert into benefit_rules (id, card_id, valid_from, status, rule) values ('rp_kw_health', 'kb_youwishup', null, 'approved', '{"confidence":0.9,"supported":true,"id":"rp_kw_health","cardId":"kb_youwishup","name":"병원·약국·스포츠 5% 할인","kind":"discount","rate":0.05,"target":{"categories":["hospital","pharmacy","sports"],"excludes":["무이자할부","gift_card"]},"limitsByTier":[{"tier":{"min":400000,"max":800000},"monthlyCap":5000},{"tier":{"min":800000,"max":null},"monthlyCap":10000}],"stacking":[{"ruleId":"rp_kw_pay","mode":"allow"}],"rawText":"병원, 약국, 스포츠 5% 할인. 병원: 종합병원, 일반병원(치과/한방), 일반의원(치과/한의원), 건강진단센터 업종 / 약국: 약국 업종 / 스포츠: 스포츠용품점, 레저용품점, 골프(연습)장, 테니스장, 볼링장, 스키장, 수영장, 종합스포츠센터, 레포츠클럽, 요가 업종. 대상 가맹점은 당사 업종분류기준에 따름. 월 할인한도: 1구간 40만원 이상 5,000원 / 2구간 80만원 이상 10,000원. 최초 사용등록일로부터 다음달 말일(실적유예기간)까지는 전월 이용실적 40만원 미만시에도 각 할인 서비스의 1구간 월 할인한도 50%까지만 할인 제공"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
