insert into card_products (id, issuer, name, type, color, grade, annual_fee, tiers, spend_excludes, variants, perks, source_url, checked_at, review_status) values ('shinhan_discountplan_plus', '신한카드', 'Discount Plan+', 'credit', '#1B2A4A', 'D', 50000, '[{"min":0,"max":400000},{"min":400000,"max":800000},{"min":800000,"max":1200000},{"min":1200000,"max":1800000},{"min":1800000,"max":null}]'::jsonb, array['gift_card','tax','school','apt_fee','gas','electric','utility']::text[], null, '[{"id":"rp_dp_k_planday","kind":"etc","name":"Plan Day — 매월 1일 할인율 2배","detail":"매월 1일 Time Plan·Daily Plan 첫 할인 거래(서비스당 1회)에 할인율 2배. 월 통합 한도·횟수 안에서","rawText":"[Plan Day 서비스] 매월 1일 Time Plan, Daily Plan 서비스 2배 할인. 매월 1일 Time Plan 서비스, Daily Plan 서비스 첫 번째 할인 거래에 할인율 2배 적용(서비스당 1회). Daily Plan 서비스의 해외 영역에는 Plan Day 서비스가 적용되지 않습니다. Plan Day 서비스는 Time Plan 서비스, Daily Plan 서비스의 월 통합 할인 한도 및 일/월 횟수 한도 내에서 제공됩니다."},{"id":"rp_dp_k_reward","kind":"etc","name":"Monthly 리워드 최대 5천원 캐시백","detail":"전월 150만원 이상 3천원, 180만원 이상 5천원을 다다음달 20일에 캐시백","rawText":"Monthly 리워드 최대 5천원 캐시백. 전월 150만원 이상 이용 시 3천원 캐시백, 전월 180만원 이상 이용 시 5천원 캐시백. 전월 이용금액을 기준으로 다다음달 20일에 캐시백이 제공됩니다."},{"id":"rp_dp_k_mart","kind":"voucher","name":"장보기 3만원 캐시백 (연 1회)","value":30000,"detail":"이마트·트레이더스·롯데마트 오프라인 3만원 이상 결제 시 연 1회. 2년차부터는 전년도 1,000만원 이상 이용 시","rawText":"[Annual Plan 서비스] 장보기 3만원 캐시백 (연 1회). 마트(이마트, 트레이더스 홀세일 클럽, 롯데마트) 3만원 이상 결제 시 3만원 캐시백. 발급 초년도의 경우 연회비 납부 시 이용 실적에 관계 없이 제공되며, 발급 2차년도부터는 연회비 납부 및 전년도 이용금액 1,000만원 이상 시 제공됩니다."},{"id":"rp_dp_k_annual","kind":"voucher","name":"스피드메이트 정비·테마파크 현장 할인","detail":"전월 30만원 이상. 스피드메이트 엔진오일 등 통합 월 1회·연 3회, 에버랜드·롯데월드 50%·캐리비안베이 30% 테마파크별 연 3회","rawText":"[Annual Plan 서비스] 스피드메이트 정비 현장 할인·테마파크 할인 (전월실적 30만원 이상). 국산차 엔진오일 교환 3만원 할인 등 통합 월 1회, 연 3회. 에버랜드, 롯데월드 자유이용권 50% 할인, 캐리비안베이 입장권 30% 할인. 테마파크별 일 1회, 연 3회. 본인 자유이용권 및 입장권에 한하여 할인됩니다."}]'::jsonb, 'https://www.shinhancard.com/pconts/html/card/apply/credit/1232390_2207.html', '2026-10-12', 'approved') on conflict (id) do update set issuer=