insert into benefit_rules (id, card_id, valid_from, status, rule) values ('rp_dp_fitness', 'shinhan_discountplan_plus', null, 'approved', '{"confidence":0.9,"supported":true,"kind":"discount","cardId":"shinhan_discountplan_plus","capGroupId":"rp_dp_monthly","rawText":"[Monthly Plan 서비스] 정기결제(공과금/디지털구독·멤버십/피트니스) 최대 20% 할인 - 공과금 10% / 디지털구독·멤버십 20% / 피트니스 5% 할인. 공과금: 아파트관리비, 도시가스, 전기요금, 통신요금(SKT/KT/LGU+). 디지털구독: 넷플릭스, 유튜브 프리미엄, 티빙, 디즈니플러스, 밀리의서재. 멤버십: 네이버플러스 멤버십, 쿠팡 와우 멤버십. 피트니스: 스포츠센터/레포츠클럽, 테니스장, 수영장, 실내/외 골프장 업종. 할인받기 전 이용금액 기준 공과금 1회 5만원, 디지털구독·멤버십 1회 1만원, 피트니스 1회 10만원까지 할인됩니다. 공과금 영역은 자동납부 시에만 할인됩니다. 공과금 중 통신 요금은 월 1회, 피트니스 영역은 일 1회 할인되며, 그 외 대상 가맹점 및 디지털구독, 멤버십 영역은 일/월 횟수 제한없이 할인됩니다. 월 통합 혜택 한도(Monthly Plan 정기결제): 40만원 이상 80만원 미만 5천원 / 80만원 이상 120만원 미만 1만원 / 120만원 이상 180만원 미만 1만 5천원 / 180만원 이상 2만원","limitsByTier":[{"tier":{"min":400000,"max":800000},"monthlyCap":5000,"dailyCount":1},{"tier":{"min":800000,"max":1200000},"monthlyCap":10000,"dailyCount":1},{"tier":{"min":1200000,"max":1800000},"monthlyCap":15000,"dailyCount":1},{"tier":{"min":1800000,"max":null},"monthlyCap":20000,"dailyCount":1}],"id":"rp_dp_fitness","name":"피트니스(스포츠센터·수영장) 5% 할인","rate":0.05,"eligibleAmountCap":100000,"target":{"excludes":["무이자할부","gift_card"],"categories":["sports"]}}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
