insert into benefit_rules (id, card_id, valid_from, status, rule) values ('rp_bf_health', 'bc_sevenflex', null, 'approved', '{"confidence":0.8,"supported":true,"kind":"discount","rate":0.07,"cardId":"bc_sevenflex","capGroupId":"rp_bf_all","limitsByTier":[{"tier":{"min":300000,"max":600000},"monthlyCap":10000},{"tier":{"min":600000,"max":900000},"monthlyCap":20000},{"tier":{"min":900000,"max":1200000},"monthlyCap":30000},{"tier":{"min":1200000,"max":null},"monthlyCap":50000}],"id":"rp_bf_health","name":"운동·골프·병원·약국 7% 할인","target":{"excludes":["무이자할부","gift_card"],"categories":["sports","hospital","pharmacy"],"channel":"offline"},"rawText":"[HEALTH&BEAUTY] 운동·골프·병원·약국·이/미용원 7% 할인. 대상 가맹점 : 헬스클럽 업종, 골프 업종, 병원/약국/동물병원, 이/미용원 업종. 골프 업종 : 골프연습장, 스크린골프, 골프경기장. 병원/약국/동물병원 : 종합병원, 병의원, 한의원, 치과, 동물병원. 오프라인 매장 결제 건에 한함. 건강진단, 산후조리원 등 기타의료기관 제외. 공통 : 백화점/쇼핑몰/할인점 내 임대매장 이용금액 제외. 할인 대상이 중복으로 해당되는 경우 할인금액이 높은 서비스가 우선 적용 (매출 건당 하나의 서비스만 적용). 카테고리별 월 할인한도: FLEX/HEALTH&BEAUTY/YUMMY/DAILY 각 20,000원, PAY 15,000원 (전월실적 60만원 미만인 경우 카테고리별 월 할인한도 10,000원). 월 통합 할인한도: 전월실적 30만원 이상 10,000원 / 60만원 이상 20,000원 / 90만원 이상 30,000원 / 120만원 이상 50,000원. 청구할인 제외: 무이자할부 이용금액, 기프트/선불카드 구매 및 충전금액, 상품권 구매금액"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
insert into benefit_rules (id, card_id, valid_from, status, rule) values ('rp_bf_flex', 'bc_sevenflex', null, 'approved', '{"confidence":0.9,"supported":true,"kind":"discount","rate":0.07,"cardId":"bc_sevenflex","capGroupId":"rp_bf_all","limitsByTier":[{"tier":{"min":300000,"max":600000},"monthlyCap":10000},{"tier":{"min":600000,"max":900000},"monthlyCap":20000},{"tier":{"min":900000,"max":1200000},"monthlyCap":30000},{"tier":{"min":1200000,"max":null},"monthlyCap":50000}],"id":"rp_bf_flex","name":"신세계백화점·W컨셉 7% 할인","target":{"excludes":["무이자할부","gift_card"],"merchants":["신세계백화점","신세계 백화점","신세계아울렛","신세계 아울렛","신세계면세점","신세계 면세점","W컨셉","W Concept","더블유컨셉"]},"rawText":"[FLEX] 신세계백화점·W concept 등 7% 할인. 대상 가맹점 : 신세계백화점(문화센터 포함), 신세계아울렛, 신세계면세점, W Concept. 신세계백화점 : 오프라인 매장 결제에 한함 (단, 문화센터의 경우 온라인 결제 포함). 전월 실적 제외 항목: FLEX 카테고리 이용금액. 공통 : 백화점/쇼핑몰/할인점 내 임대매장 이용금액 제외. 할인 대상이 중복으로 해당되는 경우 할인금액이 높은 서비스가 우선 적용 (매출 건당 하나의 서비스만 적용). 카테고리별 월 할인한도: FLEX/HEALTH&BEAUTY/YUMMY/DAILY 각 20,000원, PAY 15,000원 (전월실적 60만원 미만인 경우 카테고리별 월 할인한도 10,000원). 월 통합 할인한도: 전월실적 30만원 이상 10,000원 / 60만원 이상 20,000원 / 90만원 이상 30,000원 / 120만원 이상 50,000원. 청구할인 제외: 무이자할부 이용금액, 기프트/선불카드 구매 및 충전금액, 상품권 구매금액"}'::jsonb) on conflict (id) do update set card_id=excluded.card_id, valid_from=excluded.valid_from, status=excluded.status, rule=excluded.rule;
